{{!-- Styling parameters: class, cardClass, titleClass, labelClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Use inside {{#post}}. Native helpers hide missing neighbors. --}}
<nav class="ghcn-post-navigation{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Post navigation">{{~#prev_post~}}<a class="ghcn-post-navigation__link{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}" href="{{url}}" rel="prev"><span class="ghcn-post-navigation__label{{#if ghostcnStyles.labelClass}} {{ghostcnStyles.labelClass}}{{/if}}">Previous post</span><span class="ghcn-post-navigation__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{title}}</span></a>{{~/prev_post~}}{{~#next_post~}}<a class="ghcn-post-navigation__link{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}} ghcn-post-navigation__link--next" href="{{url}}" rel="next"><span class="ghcn-post-navigation__label{{#if ghostcnStyles.labelClass}} {{ghostcnStyles.labelClass}}{{/if}}">Next post</span><span class="ghcn-post-navigation__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{title}}</span></a>{{~/next_post~}}</nav>
{{/with}}

.ghcn-post-navigation { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 1em; margin-block: 2em; }
.ghcn-post-navigation:empty { display: none; }
.ghcn-post-navigation__link { min-width: 0; display: flex; flex-direction: column; gap: .5em; padding: 1.25em; border: 1px solid var(--border); border-radius: var(--radius); background: var(--card); color: var(--card-foreground); text-decoration: none; }
.ghcn-post-navigation__link--next { grid-column: 2; text-align: right; }
.ghcn-post-navigation__label { font-size: .75em; color: var(--muted-foreground); }
.ghcn-post-navigation__title { font-weight: 600; overflow-wrap: anywhere; }
.ghcn-post-navigation__link:hover .ghcn-post-navigation__title { text-decoration: underline; }
.ghcn-post-navigation__link:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
@media(max-width:620px) { .ghcn-post-navigation { grid-template-columns: 1fr; } .ghcn-post-navigation__link--next { grid-column: 1; } }
